mapper.select:
SELECT u.*, aut.dept_id AS deptId FROM ad_user u INNER JOIN ad_user_tenant aut ON aut.user_id = u.id AND aut.is_deleted = '0' WHERE u.is_deleted = '0' AND aut.tenant_id = #{tenantId} AND aut.status = 1
AND u.id NOT IN
#{uid}
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') )
AND u.status = #{status}
AND aut.dept_id = #{deptId}
ORDER BY u.create_time DESC
